import {DOORS,walkableFoot,safePosition} from './world.js';
export const newRelationship=()=>({bond:30,following:true,holdingHands:false,talk:0,memories:[],events:[],activity:null,restedUntil:0,visited:[],gathered:0});
const $=id=>document.getElementById(id),cap=(n,min,max)=>Math.max(min,Math.min(max,n));
const escape=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function createCompanion(api){
 const {state,openModal,closeModal,toast,saveGame,dialog,give,take,count,travel}=api;let nightTimer=null;
 const rel=()=>state.world.relationship;
 const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
 function bond(n,event){const r=rel();r.bond=cap(r.bond+n,0,100);if(event)r.events=[event,...r.events].slice(0,12);}
 function ensure(){if(state.quest<5)return null;if(!state.companion||state.companion.scene!==state.scene){const pos=safePosition(state.scene,state.player.x+24,state.player.y+24,state.quest);state.companion={id:'amo-companion',type:'liora',name:'Амо',marker:'♡',scene:state.scene,dir:'down',...pos,moving:false,stalled:0};}return state.companion;}
 function nearby(){if(state.quest<5)return null;const c=ensure();if((rel().following||state.scene==='home')&&distance(c,state.player)<65)return{kind:'world',action:'companion',label:'Амо · поговорить',x:c.x,y:c.y};return null;}
 function navigate(c,target,dt){const d=distance(c,target);if(d<8)return false;const a=Math.atan2(target.y-c.y,target.x-c.x),speed=state.player.moving?Math.max(110,api.stats().speed+8):85;let best=null;for(const turn of[0,.5,-.5,1,-1,1.6,-1.6]){const x=c.x+Math.cos(a+turn)*speed*dt,y=c.y+Math.sin(a+turn)*speed*dt;if(walkableFoot(state.scene,x,y,state.quest)){const score=Math.hypot(target.x-x,target.y-y);if(!best||score<best.score)best={x,y,score};}}if(best){const dx=best.x-c.x,dy=best.y-c.y;c.x=best.x;c.y=best.y;c.dir=Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up';return true;}return false;}
 function update(dt){if(state.quest<5)return;const r=rel(),c=ensure(),p=state.player;
  if(state.romancePose){state.romancePose.t+=dt;if(state.romancePose.kind!=='night'&&state.romancePose.t>=state.romancePose.duration){state.romancePose=null;saveGame();}}
  if(!r.following&&state.scene!=='home'){c.moving=false;return;}
  const activePose=state.romancePose&&state.romancePose.kind!=='night';
  if(activePose){c.x=p.x+22;c.y=p.y;c.moving=false;return;}
  if(state.scene==='home'&&!r.following){c.x=415;c.y=485;c.dir='left';c.moving=false;}
  else{const d=distance(c,p),offset=r.holdingHands?22:35,target={x:p.x+offset,y:p.y+9};if(d>200){Object.assign(c,safePosition(state.scene,p.x+offset,p.y+20,state.quest));}c.moving=distance(c,p)>(r.holdingHands?24:43)?navigate(c,target,dt):false;}
  if(r.following&&!r.visited.includes(state.scene)){r.visited.push(state.scene);const lines={district:'Здесь пахнет хлебом. Слышишь, как снова шумит город?',inn:'Может, сегодня никуда не спешить? Возьмём столик у огня.',church:'Я поставлю свечу. Не за прошлое — за нашу дорогу вперёд.',home:'Вот оно. Место, куда мы будем возвращаться.',workshop:'Давай я подержу доску. Вдвоём получится ровнее.',stables:'Этот серый конь смотрит на тебя так, будто уже знает все твои тайны.'};if(lines[state.scene])toast('Амо: «'+lines[state.scene]+'»');}
  const activity=r.activity;if(activity){activity.walked=(activity.walked||0)+(p.moving?dt:0);if(state.scene===activity.scene&&distance(p,activity)<55&&(activity.kind!=='walk'||activity.walked>2)){r.activity=null;completeActivity(activity);}}
 }
 const talks=[
  ['Когда меня забрали, я боялась забыть не себя. Твой голос. Как ты говоришь моё имя.','Теперь у нас будет время услышать его ещё тысячу раз.'],
  ['Я всё ещё хочу к морю. Но теперь знаю: дом — это не точка на карте.','Мы увидим море. А потом вернёмся в наш дом.'],
  ['Ты всегда так серьёзно держишь инструменты. Даже когда просто режешь хлеб.','Кто-то ведь должен защищать нас от упрямой корочки.'],
  ['Если однажды у нас будет сад, оставь мне маленький уголок для цветов.','Оставлю. И буду напоминать тебе поливать их.'],
  ['Мне нравится идти рядом и ничего не говорить. Не потому, что слов нет. Просто всё уже понятно.','Тогда пойдём. Я рядом.']
 ];
 function talk(){const r=rel(),i=r.talk++%talks.length;closeModal();dialog([['Амо',talks[i][0],'liora','РЯДОМ С ТОБОЙ'],['Морриган',talks[i][1],'hero','']],()=>{if(!r.memories.includes(i)){r.memories.push(i);bond(2,'Разговор по душам');}saveGame();});}
 function pose(kind){const p=state.player;if(state.scene==='overworld'&&state.enemies.some(e=>e.hp>0&&distance(e,p)<150)){toast('Амо: «Я рядом. Сначала разберись с тенями».');return;}closeModal();api.resetInputs();p.moving=false;p.action=null;state.pendingHits=[];rel().holdingHands=false;state.romancePose={kind,t:0,duration:kind==='kiss'?3.4:kind==='hug'?2.8:4.2,x:p.x,y:p.y};bond(kind==='kiss'?3:2,kind==='kiss'?'Поцелуй на тихой дороге':'Тёплое объятие');saveGame();}
 function schedule(kind){const targets={walk:{scene:'district',x:850,y:470,name:'Прогулка по площади'},dinner:{scene:'inn',x:320,y:340,name:'Ужин у огня'},fishing:{scene:'overworld',x:553,y:531,name:'Рыбалка вдвоём'},garden:{scene:'district',x:805,y:744,name:'Вместе в огород'}};
  const r=rel(),t=targets[kind];if(kind==='dinner'&&state.player.gold<12){toast('Для ужина нужно 12 монет');return;}if(kind==='garden'&&!state.world.house.garden){toast('Сначала разбейте домашний огород');return;}r.following=true;r.activity={...t,kind,walked:0};closeModal();toast('Амо: «Пойдём. Я с тобой». '+t.name);saveGame();}
 function completeActivity(a){const r=rel(),p=state.player;if(a.kind==='dinner'){if(p.gold<12){toast('На ужин не хватило монет');return;}p.gold-=12;p.hp=Math.min(p.maxHp,p.hp+45);p.mp=Math.min(p.maxMp,p.mp+45);}
  if(a.kind==='fishing')give('fish',2);
  if(a.kind==='garden'){const h=state.world.house;if(h.plantedAt!==null)h.plantedAt-=15;else if(take('seed'))h.plantedAt=state.world.elapsed;}
  bond(4,a.name);state.romancePose={kind:a.kind,t:0,duration:4.5,x:p.x,y:p.y};api.resetInputs();p.moving=false;const lines={walk:'Спасибо, что мы можем просто гулять. Без погони. Без прощаний.',dinner:'Давай запомним этот вечер. Тёплый хлеб, огонь и ты напротив.',fishing:'У нас две рыбы! Одну поймала я. Вторая, кажется, сама захотела с нами домой.',garden:'Я полью грядки. А ты проверь, хватит ли досок для маленькой скамейки.'};toast('Амо: «'+lines[a.kind]+'»',true);saveGame();api.updateQuest();}
 function night(){const h=state.world.house,r=rel();if(state.scene!=='home'||!h.owned||h.stage<4){toast('Для вечера наедине вернитесь в свой достроенный дом');return;}if(r.bond<35){toast('Побудьте вместе: близость открывается при доверии 35');return;}closeModal();api.resetInputs();rel().holdingHands=false;state.romancePose={kind:'night',t:0,duration:4.8,started:performance.now()};
  let overlay=$('romantic-night');if(!overlay){overlay=document.createElement('section');overlay.id='romantic-night';overlay.innerHTML='<div class="night-stars">✦ · ✧ · ✦</div><small>ВАШ ДОМ · ТОЛЬКО ВЫ ДВОЕ</small><h2>Там, где мы дома</h2><canvas id="night-canvas" width="360" height="300"></canvas><p>За окном стихает мир.<br>Можно просто остаться рядом.</p><div class="night-hearts">♡ <span>♡</span> ♡</div>';document.getElementById('app').appendChild(overlay);}overlay.classList.add('visible');
  clearTimeout(nightTimer);nightTimer=setTimeout(()=>{overlay.classList.remove('visible');state.romancePose=null;state.player.hp=state.player.maxHp;state.player.mp=state.player.maxMp;r.restedUntil=state.world.elapsed+240;bond(6,'Ночь вместе в общем доме');saveGame();toast('Утро. Амо: «Не вставай пока. Ещё одну минутку».',true);},4800);
 }
 function renderModal(kind){if(kind!=='companion')return false;const r=rel(),h=state.world.house,el=$('modal-content');if(state.quest<5){el.innerHTML='<small class="modal-kicker">ТВОЙ СВЕТ</small><h2>Верни Амо</h2><p>Сначала найдите её в святилище.</p>';return true;}
  const b=(action,label,disabled=false)=>`<button class="rpg-button" data-romance="${action}" ${disabled?'disabled':''}>${label}</button>`;
  $('modal').querySelector('.modal-card').classList.add('rpg-folio');el.innerHTML=`<small class="modal-kicker">ИСТОРИЯ, КОТОРУЮ ВЫ ПИШЕТЕ ВМЕСТЕ</small><h2>Амо</h2><div class="bond-meter"><span>♡ Доверие</span><strong>${Math.floor(r.bond)} / 100</strong><i style="--bond:${r.bond}%"></i></div><p>Тёмно-русые волосы, знакомая улыбка. Она здесь. И больше не хочет оставаться лишь воспоминанием.</p><div class="romance-actions">${b('talk','Поговорить по душам')}${b('hug','Обнять')}${b('kiss','Поцеловать')}${b('hands',r.holdingHands?'Отпустить руку':'Взяться за руки')}${b('follow',r.following?'Попросить подождать дома':'Пойдём со мной')}</div><h3>Общее время</h3><div class="romance-actions">${b('walk','Прогуляться по кварталу')}${b('dinner','Поужинать в трактире · 12 монет',state.player.gold<12)}${b('fishing','Порыбачить у моста')}${b('garden','Вместе заняться огородом',!h.garden)}${b('night','Провести ночь вместе · дома',!h.owned||h.stage<4||r.bond<35)}</div>${r.activity?`<p class="shared-plan">✦ Сейчас: ${escape(r.activity.name)}. ◇ показывает дорогу.</p>`:''}<p>Когда Амо рядом, вы получаете дополнительный материал при сборе. Она помогает с огородом и поддерживает в работе.</p>${r.events.length?'<h3>Ваши воспоминания</h3><ul class="shared-memories">'+r.events.slice(0,5).map(e=>'<li>♡ '+escape(e)+'</li>').join('')+'</ul>':''}`;return true;
 }
 $('modal-content').addEventListener('click',e=>{const b=e.target.closest('[data-romance]');if(!b||b.disabled)return;const action=b.dataset.romance,r=rel();if(action==='talk')talk();else if(action==='hug'||action==='kiss')pose(action);else if(action==='hands'){r.holdingHands=!r.holdingHands;r.following=true;closeModal();toast(r.holdingHands?'Амо берёт тебя за руку.':'Амо остаётся рядом.');saveGame();}else if(action==='follow'){r.following=!r.following;r.holdingHands=false;closeModal();toast(r.following?'Амо отправляется с тобой.':'Амо будет ждать дома.');saveGame();}else if(action==='night')night();else schedule(action);});
 const ui=document.createElement('button');ui.id='companion-button';ui.className='icon-button folio-button';ui.setAttribute('aria-label','Амо · отношения и совместные занятия');ui.title='Амо';ui.textContent='♡';ui.hidden=true;ui.addEventListener('click',()=>openModal('companion'));document.querySelector('.utility-buttons').prepend(ui);
 function target(){const a=rel()?.activity;if(!a)return null;if(state.scene===a.scene)return a;if(state.scene==='overworld')return{x:512,y:1490};if(state.scene==='district'){const d=DOORS.find(d=>d.id===(a.scene==='overworld'?'forest':a.scene));return d||null;}return{x:320,y:565};}
 function assist(kind,id,qty=1){if(state.quest<5||!rel().following||!state.companion||distance(state.companion,state.player)>90)return;if(kind==='gather'){give(id,1);rel().gathered++;bond(.5);toast('Амо помогла собрать ещё: +1 '+api.itemName(id),true);}else if(kind==='build'){bond(3,'Вы строили дом вместе');toast('Амо: «Смотри, уже получается наш дом».');}else if(kind==='work')bond(.5);saveGame();}
 function hud(){ui.hidden=state.quest<5;}
 return{update,nearby,renderModal,target,assist,hud,ensure};
}
export function drawRomance(c,state,art,sprite){const pose=state.romancePose,r=state.world?.relationship,p=state.player;if(!r||state.quest<5)return;
 const hands=r.following&&r.holdingHands&&state.companion&&Math.hypot(p.x-state.companion.x,p.y-state.companion.y)<62;
 if(pose?.kind==='night'){const cv=document.getElementById('night-canvas');if(cv){const cc=cv.getContext('2d');cc.clearRect(0,0,360,300);cc.imageSmoothingEnabled=false;const t=(performance.now()-pose.started)/1000;if(art.bed){const i=Math.floor(t*2)%4,w=art.bed.width/2,h=art.bed.height/2;cc.drawImage(art.bed,i%2*w,Math.floor(i/2)*h,w,h,25,0,310,280);}else{sprite(cc,140,225,p.type,'right',0,3);sprite(cc,205,225,'liora','left',0,3);cc.fillStyle='#85739b';cc.fillRect(75,145,210,100);cc.fillStyle='#c1b0d2';cc.fillRect(75,145,210,8);}cc.font='20px Georgia';cc.textAlign='center';for(let i=0;i<5;i++){cc.globalAlpha=.4+Math.sin(t*2+i)*.3;cc.fillStyle='#e9b6ca';cc.fillText('♡',90+i*45,140-((t*25+i*31)%125));}cc.globalAlpha=1;}return;}
 if(!pose&&!hands)return;let frame=0;
 if(pose?.kind==='hug')frame=pose.t<.35?1:pose.t<2.25?2:1;
 if(pose?.kind==='kiss')frame=pose.t<.4?1:pose.t<.8?2:pose.t<2.8?3:2;
 const bob=hands&&p.moving?Math.sin(state.time*12)*1.3:0;
 if(art.couple){const row={paladin:0,mage:1,rogue:2,necromancer:3}[p.type]||0,w=art.couple.width/4,h=art.couple.height/4;c.drawImage(art.couple,frame*w+w*.04,row*h+h*.02,w*.92,h*.96,p.x-43,p.y-66+bob,86,78);}else{sprite(c,p.x-11,p.y,p.type,'right',state.time);sprite(c,p.x+18,p.y,'liora','left',state.time);}
 if(pose&&['hug','kiss','walk'].includes(pose.kind)){c.font='13px Georgia';c.textAlign='center';for(let i=0;i<3;i++){c.fillStyle='#efb9c9';c.globalAlpha=Math.max(0,1-((pose.t+i*.45)%1.4)/1.4);c.fillText('♡',p.x-18+i*17,p.y-64-((pose.t*17+i*8)%25));}c.globalAlpha=1;}
 if(pose?.kind==='dinner'){c.fillStyle='#6f4d2e';c.fillRect(p.x-48,p.y-25,96,27);c.fillStyle='#b58a4f';for(let j=0;j<3;j++)c.fillRect(p.x-46,p.y-24+j*8,92,2);for(const x of[-22,22]){c.fillStyle='#e0d8b7';c.beginPath();c.ellipse(p.x+x,p.y-14,10,5,0,0,7);c.fill();c.fillStyle='#a16a36';c.beginPath();c.ellipse(p.x+x,p.y-14,7,3,0,0,7);c.fill();}}
 if(pose?.kind==='fishing'){c.strokeStyle='#9a8154';c.lineWidth=2;c.beginPath();c.moveTo(p.x+18,p.y-28);c.lineTo(p.x+58,p.y-52+Math.sin(pose.t*3));c.stroke();c.strokeStyle='#ece4bf99';c.lineWidth=.7;c.beginPath();c.moveTo(p.x+58,p.y-52);c.lineTo(p.x+70,p.y+2+Math.sin(pose.t*2)*2);c.stroke();c.fillStyle='#db8874';c.fillRect(p.x+68,p.y,3,4);}
 if(pose?.kind==='garden'){c.fillStyle='#7fa0a0';c.fillRect(p.x+24,p.y-32,12,10);c.strokeStyle='#b4dbe1';for(let j=0;j<5;j++){c.beginPath();c.moveTo(p.x+37+j*3,p.y-26+j*3);c.lineTo(p.x+39+j*3,p.y-21+j*3);c.stroke();}}
}
